import { createSchema } from "graphql-yoga";
import { initialProducts, initialOrders, initialCustomers } from "./sample-data.js";
import { WebhookDispatcher } from "./webhooks.js";
import crypto from "crypto";

const typeDefs = /* GraphQL */ `
  type Query {
    shop: AdminShop!
    products(first: Int = 50): [Product!]!
    product(id: ID!): Product
    orders(first: Int = 50): [Order!]!
    order(id: ID!): Order
    customers(first: Int = 50): [Customer!]!
    analyticsOverview: AnalyticsOverview!
  }

  type Mutation {
    productCreate(input: ProductInput!): ProductPayload!
    productUpdate(id: ID!, input: ProductInput!): ProductPayload!
    productDelete(id: ID!): DeletePayload!
    orderCreate(input: OrderCreateInput!): OrderPayload!
    fulfillmentCreate(orderId: ID!, trackingCompany: String, trackingNumber: String): OrderPayload!
  }

  type AdminShop {
    id: ID!
    name: String!
    domain: String!
    plan: String!
    currencyCode: String!
    timezone: String!
  }

  type Product {
    id: ID!
    title: String!
    handle: String!
    description: String!
    vendor: String!
    productType: String!
    status: String!
    tags: [String!]!
    images: [String!]!
    variants: [ProductVariant!]!
    totalInventory: Int!
    createdAt: String!
  }

  type ProductVariant {
    id: ID!
    productId: ID!
    title: String!
    sku: String!
    price: Float!
    compareAtPrice: Float
    inventoryQuantity: Int!
  }

  type Order {
    id: ID!
    orderNumber: Int!
    name: String!
    email: String!
    financialStatus: String!
    fulfillmentStatus: String!
    currencyCode: String!
    subtotalPrice: Float!
    totalTax: Float!
    totalShipping: Float!
    totalDiscounts: Float!
    totalPrice: Float!
    lineItems: [OrderLineItem!]!
    shippingAddress: Address
    createdAt: String!
  }

  type OrderLineItem {
    id: ID!
    title: String!
    sku: String
    quantity: Int!
    price: Float!
    fulfillmentStatus: String!
  }

  type Address {
    firstName: String
    lastName: String
    address1: String!
    city: String!
    country: String!
    zip: String!
  }

  type Customer {
    id: ID!
    displayName: String!
    email: String!
    phone: String
    ordersCount: Int!
    totalSpent: Float!
    tags: [String!]!
    createdAt: String!
  }

  type AnalyticsOverview {
    totalSales: Float!
    ordersCount: Int!
    conversionRate: Float!
    averageOrderValue: Float!
    sessionsCount: Int!
  }

  type ProductPayload {
    product: Product
    userErrors: [UserError!]!
  }

  type OrderPayload {
    order: Order
    userErrors: [UserError!]!
  }

  type DeletePayload {
    deletedId: ID
    userErrors: [UserError!]!
  }

  type UserError {
    field: [String!]
    message: String!
  }

  input ProductInput {
    title: String!
    handle: String
    description: String
    vendor: String
    productType: String
    status: String
    tags: [String!]
    price: Float
    sku: String
  }

  input OrderCreateInput {
    email: String!
    lineItems: [OrderLineItemInput!]!
  }

  input OrderLineItemInput {
    variantId: ID!
    quantity: Int!
  }
`;

export function createAdminSchema(tenantId: string) {
  const products = [...initialProducts];
  const orders = [...initialOrders];
  const customers = [...initialCustomers];

  return createSchema({
    typeDefs,
    resolvers: {
      Query: {
        shop: () => ({
          id: tenantId,
          name: "Apex Apparel Co.",
          domain: "apex-apparel.vendr.local",
          plan: "ENTERPRISE",
          currencyCode: "USD",
          timezone: "UTC",
        }),
        products: () => products,
        product: (_: unknown, { id }: { id: string }) => products.find((p) => p.id === id),
        orders: () => orders,
        order: (_: unknown, { id }: { id: string }) => orders.find((o) => o.id === id),
        customers: () => customers,
        analyticsOverview: () => {
          const totalSales = orders.reduce((acc, o) => acc + o.totalPrice, 0);
          const ordersCount = orders.length;
          const aov = ordersCount > 0 ? totalSales / ordersCount : 0;
          return {
            totalSales: Math.round(totalSales * 100) / 100,
            ordersCount,
            conversionRate: 3.84,
            averageOrderValue: Math.round(aov * 100) / 100,
            sessionsCount: 14250,
          };
        },
      },
      Mutation: {
        productCreate: async (_: unknown, { input }: any) => {
          const id = `prod_${crypto.randomUUID().slice(0, 8)}`;
          const handle =
            input.handle ||
            input.title
              .toLowerCase()
              .replace(/[^a-z0-9]+/g, "-")
              .replace(/(^-|-$)/g, "");

          const newProduct = {
            id,
            tenantId,
            title: input.title,
            handle,
            description: input.description || "",
            descriptionHtml: `<p>${input.description || ""}</p>`,
            vendor: input.vendor || "Apex Apparel",
            productType: input.productType || "General",
            status: input.status || "ACTIVE",
            tags: input.tags || [],
            images: [
              "https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=800&auto=format&fit=crop&q=80",
            ],
            options: [{ name: "Title", values: ["Default"] }],
            variants: [
              {
                id: `var_${crypto.randomUUID().slice(0, 8)}`,
                productId: id,
                title: "Default",
                sku: input.sku || `SKU-${Math.floor(1000 + Math.random() * 9000)}`,
                price: input.price || 45.0,
                requiresShipping: true,
                selectedOptions: [{ name: "Title", value: "Default" }],
                inventoryQuantity: 50,
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
              },
            ],
            totalInventory: 50,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          };

          products.unshift(newProduct);
          await WebhookDispatcher.dispatch("products/create", tenantId, newProduct);
          return { product: newProduct, userErrors: [] };
        },
        productDelete: async (_: unknown, { id }: { id: string }) => {
          const index = products.findIndex((p) => p.id === id);
          if (index !== -1) {
            const [deleted] = products.splice(index, 1);
            await WebhookDispatcher.dispatch("products/delete", tenantId, { id: deleted.id });
            return { deletedId: id, userErrors: [] };
          }
          return { deletedId: null, userErrors: [{ field: ["id"], message: "Product not found" }] };
        },
        orderCreate: async (_: unknown, { input }: any) => {
          const orderNumber = Math.floor(1000 + Math.random() * 9000);
          const newOrder = {
            id: `ord_${orderNumber}`,
            tenantId,
            orderNumber,
            name: `#${orderNumber}`,
            email: input.email,
            financialStatus: "PAID" as const,
            fulfillmentStatus: "UNFULFILLED" as const,
            currencyCode: "USD" as const,
            subtotalPrice: 120.0,
            totalTax: 9.6,
            totalShipping: 0,
            totalDiscounts: 0,
            totalPrice: 129.6,
            lineItems: input.lineItems.map((li: any) => ({
              id: `item_${crypto.randomUUID().slice(0, 6)}`,
              title: "Product Item",
              sku: "SKU-AUTO",
              quantity: li.quantity,
              price: 60.0,
              fulfillmentStatus: "UNFULFILLED",
            })),
            shippingAddress: {
              firstName: "Store",
              lastName: "Customer",
              address1: "123 Commerce Way",
              city: "New York",
              country: "United States",
              zip: "10001",
            },
            fulfillments: [],
            tags: ["online", "web"],
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          };

          orders.unshift(newOrder);
          await WebhookDispatcher.dispatch("orders/create", tenantId, newOrder);
          return { order: newOrder, userErrors: [] };
        },
        fulfillmentCreate: async (_: unknown, { orderId, trackingCompany, trackingNumber }: any) => {
          const order = orders.find((o) => o.id === orderId);
          if (!order) {
            return { order: null, userErrors: [{ field: ["orderId"], message: "Order not found" }] };
          }

          order.fulfillmentStatus = "FULFILLED";
          order.fulfillments.push({
            id: `ful_${crypto.randomUUID().slice(0, 6)}`,
            orderId: order.id,
            status: "SHIPPED",
            trackingCompany: trackingCompany || "UPS Ground",
            trackingNumber: trackingNumber || `1Z9999999999999999`,
            trackingUrl: `https://ups.com/track`,
            createdAt: new Date().toISOString(),
          });

          await WebhookDispatcher.dispatch("orders/fulfilled", tenantId, order);
          return { order, userErrors: [] };
        },
      },
    },
  });
}

import { Cart, CartLine, ProductVariant, Order } from "@vendr/types";
import { VendrWasmEngine } from "@vendr/wasm-engine";
import crypto from "crypto";

const cartsMemoryStore = new Map<string, Cart>();
const wasmEngine = new VendrWasmEngine();

export class CheckoutService {
  /**
   * Get or initialize a cart
   */
  static getCart(cartId: string): Cart | undefined {
    return cartsMemoryStore.get(cartId);
  }

  /**
   * Create a new shopping cart
   */
  static async createCart(tenantId: string, lines: { variant: ProductVariant; quantity: number }[]): Promise<Cart> {
    const id = `cart_${crypto.randomUUID()}`;
    const cartLines: CartLine[] = lines.map((l) => ({
      id: `line_${crypto.randomUUID()}`,
      merchandiseId: l.variant.id,
      quantity: l.quantity,
      variant: l.variant,
    }));

    const cart: Cart = {
      id,
      tenantId,
      lines: cartLines,
      subtotalAmount: 0,
      totalTaxAmount: 0,
      totalShippingAmount: 0,
      totalDiscountAmount: 0,
      totalAmount: 0,
      currencyCode: "USD",
      discountCodes: [],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    await this.recalculateCart(cart);
    cartsMemoryStore.set(id, cart);
    return cart;
  }

  /**
   * Add lines to existing cart
   */
  static async addLines(cartId: string, lines: { variant: ProductVariant; quantity: number }[]): Promise<Cart> {
    const cart = cartsMemoryStore.get(cartId);
    if (!cart) throw new Error("Cart not found");

    for (const item of lines) {
      const existing = cart.lines.find((l) => l.merchandiseId === item.variant.id);
      if (existing) {
        existing.quantity += item.quantity;
      } else {
        cart.lines.push({
          id: `line_${crypto.randomUUID()}`,
          merchandiseId: item.variant.id,
          quantity: item.quantity,
          variant: item.variant,
        });
      }
    }

    await this.recalculateCart(cart);
    cart.updatedAt = new Date().toISOString();
    cartsMemoryStore.set(cartId, cart);
    return cart;
  }

  /**
   * Remove lines from cart
   */
  static async removeLines(cartId: string, lineIds: string[]): Promise<Cart> {
    const cart = cartsMemoryStore.get(cartId);
    if (!cart) throw new Error("Cart not found");

    cart.lines = cart.lines.filter((l) => !lineIds.includes(l.id));
    await this.recalculateCart(cart);
    cart.updatedAt = new Date().toISOString();
    cartsMemoryStore.set(cartId, cart);
    return cart;
  }

  /**
   * Apply discount code via WASM Functions Engine
   */
  static async applyDiscountCode(cartId: string, code: string): Promise<Cart> {
    const cart = cartsMemoryStore.get(cartId);
    if (!cart) throw new Error("Cart not found");

    if (!cart.discountCodes.includes(code)) {
      cart.discountCodes.push(code);
    }

    await this.recalculateCart(cart);
    cart.updatedAt = new Date().toISOString();
    cartsMemoryStore.set(cartId, cart);
    return cart;
  }

  /**
   * Recalculate totals, taxes, and WASM discount allocations
   */
  private static async recalculateCart(cart: Cart): Promise<void> {
    let subtotal = 0;
    for (const line of cart.lines) {
      subtotal += line.variant.price * line.quantity;
    }

    // Run WASM discount function
    const wasmResult = await wasmEngine.runCartDiscountFunction({ cart });
    let totalDiscount = 0;

    for (const disc of wasmResult.discounts) {
      if (disc.value.percentage) {
        totalDiscount += subtotal * (disc.value.percentage / 100);
      } else if (disc.value.fixedAmount) {
        totalDiscount += disc.value.fixedAmount.amount;
      }
    }

    totalDiscount = Math.min(totalDiscount, subtotal);
    const taxRate = 0.08; // 8% standard tax
    const shipping = subtotal > 100 ? 0 : 12; // Free shipping over $100
    const taxableSubtotal = Math.max(0, subtotal - totalDiscount);
    const tax = Math.round(taxableSubtotal * taxRate * 100) / 100;

    cart.subtotalAmount = subtotal;
    cart.totalDiscountAmount = totalDiscount;
    cart.totalShippingAmount = shipping;
    cart.totalTaxAmount = tax;
    cart.totalAmount = Math.max(0, subtotal - totalDiscount + tax + shipping);
  }

  /**
   * Complete checkout and generate confirmed order
   */
  static async completeCheckout(cartId: string, email: string, shippingAddress: any): Promise<Order> {
    const cart = cartsMemoryStore.get(cartId);
    if (!cart) throw new Error("Cart not found");
    if (cart.lines.length === 0) throw new Error("Cannot checkout empty cart");

    // Run checkout validation rules
    const validation = await wasmEngine.runCheckoutValidationFunction({ cart });
    if (validation.errors.length > 0) {
      throw new Error(validation.errors[0].localizedMessage);
    }

    const orderNumber = Math.floor(1000 + Math.random() * 9000);
    const order: Order = {
      id: `ord_${crypto.randomUUID()}`,
      tenantId: cart.tenantId,
      orderNumber,
      name: `#${orderNumber}`,
      email,
      financialStatus: "PAID",
      fulfillmentStatus: "UNFULFILLED",
      currencyCode: cart.currencyCode,
      subtotalPrice: cart.subtotalAmount,
      totalTax: cart.totalTaxAmount,
      totalShipping: cart.totalShippingAmount,
      totalDiscounts: cart.totalDiscountAmount,
      totalPrice: cart.totalAmount,
      shippingAddress,
      lineItems: cart.lines.map((l) => ({
        id: `item_${crypto.randomUUID()}`,
        orderId: `ord_${orderNumber}`,
        variantId: l.variant.id,
        title: l.variant.title,
        sku: l.variant.sku,
        quantity: l.quantity,
        price: l.variant.price,
        totalDiscount: 0,
        fulfillmentStatus: "UNFULFILLED",
      })),
      fulfillments: [],
      tags: ["online", "web"],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    // Clean up cart after checkout
    cartsMemoryStore.delete(cartId);
    return order;
  }
}

import test from "node:test";
import assert from "node:assert/strict";
import { CheckoutService } from "./checkout.js";
import { initialProducts } from "./sample-data.js";
import { WebhookDispatcher } from "./webhooks.js";
import { buildApp } from "./server.js";

test("VENDR Core API & Multi-Tenant Engine Test Suite", async (t) => {
  await t.test("Cart Creation & Line Item Management", async () => {
    const variant = initialProducts[0].variants[0];
    const cart = await CheckoutService.createCart("ten_test", [
      { variant, quantity: 2 },
    ]);

    assert.ok(cart.id.startsWith("cart_"));
    assert.equal(cart.lines.length, 1);
    assert.equal(cart.subtotalAmount, variant.price * 2);
    assert.equal(cart.totalAmount > 0, true);
  });

  await t.test("WASM Functions Discount Application (VIP20 -> 20% off)", async () => {
    const variant = initialProducts[0].variants[0];
    const cart = await CheckoutService.createCart("ten_test", [
      { variant, quantity: 1 },
    ]);

    const initialTotal = cart.subtotalAmount;
    const discountedCart = await CheckoutService.applyDiscountCode(cart.id, "VIP20");

    assert.equal(discountedCart.discountCodes.includes("VIP20"), true);
    assert.equal(discountedCart.totalDiscountAmount, initialTotal * 0.2);
  });

  await t.test("Checkout Engine Finalizes Order & Returns Order Number", async () => {
    const variant = initialProducts[0].variants[0];
    const cart = await CheckoutService.createCart("ten_test", [
      { variant, quantity: 1 },
    ]);

    const order = await CheckoutService.completeCheckout(
      cart.id,
      "test@buyer.com",
      {
        firstName: "Jane",
        lastName: "Doe",
        address1: "100 Market St",
        city: "San Francisco",
        country: "US",
        zip: "94105",
      }
    );

    assert.ok(order.id.startsWith("ord_"));
    assert.equal(typeof order.orderNumber, "number");
    assert.equal(order.financialStatus, "PAID");
    assert.equal(order.lineItems.length, 1);
  });

  await t.test("Signed Webhook HMAC Delivery Verification", async () => {
    let captured = false;
    WebhookDispatcher.register({
      id: "sub_mock",
      tenantId: "ten_test",
      topic: "products/create",
      endpoint: "https://mock.httpbin.org/post",
      secret: "super-secret-key-12345",
    });

    // Webhook should dispatch without unhandled rejection
    await WebhookDispatcher.dispatch("products/create", "ten_test", {
      id: "prod_test",
      title: "Test Shirt",
    });

    assert.ok(true);
  });

  await t.test("Fastify Health Check REST Endpoint", async () => {
    const app = await buildApp();
    const res = await app.inject({
      method: "GET",
      url: "/api/v1/health",
    });

    assert.equal(res.statusCode, 200);
    const body = JSON.parse(res.body);
    assert.equal(body.status, "ok");
    assert.equal(body.engine, "VENDR Sovereign Commerce Engine");
    await app.close();
  });
});

import Fastify from "fastify";
import cors from "@fastify/cors";
import { resolveTenant } from "./tenant.js";
import { createStorefrontSchema } from "./storefront-schema.js";
import { createAdminSchema } from "./admin-schema.js";
import { createYoga } from "graphql-yoga";
import { initialProducts, initialOrders } from "./sample-data.js";
import { WebhookDispatcher } from "./webhooks.js";

export async function buildApp() {
  const app = Fastify({
    logger: {
      level: process.env.LOG_LEVEL || "info",
    },
  });

  await app.register(cors, {
    origin: true,
    credentials: true,
  });

  // Health check endpoint
  app.get("/api/v1/health", async () => {
    return {
      status: "ok",
      version: "1.0.0",
      engine: "VENDR Sovereign Commerce Engine",
      timestamp: new Date().toISOString(),
    };
  });

  // REST Store summary
  app.get("/api/v1/store", async (req) => {
    const tenant = resolveTenant(req);
    return {
      id: tenant.id,
      name: tenant.name,
      slug: tenant.slug,
      currencyCode: tenant.currencyCode,
      domain: tenant.domain || `${tenant.slug}.vendr.local`,
    };
  });

  // REST Products listing
  app.get("/api/v1/products", async () => {
    return {
      products: initialProducts,
      count: initialProducts.length,
    };
  });

  // REST Orders listing
  app.get("/api/v1/orders", async () => {
    return {
      orders: initialOrders,
      count: initialOrders.length,
    };
  });

  // Register Webhook Subscription
  app.post("/api/v1/webhooks/subscribe", async (req, reply) => {
    const tenant = resolveTenant(req);
    const { topic, endpoint, secret } = req.body as any;

    if (!topic || !endpoint || !secret) {
      return reply.status(400).send({ error: "Missing required webhook parameters" });
    }

    WebhookDispatcher.register({
      id: `sub_${Date.now()}`,
      tenantId: tenant.id,
      topic,
      endpoint,
      secret,
    });

    return { success: true, topic, endpoint };
  });

  // Mount Storefront GraphQL API Yoga handler
  app.route({
    url: "/api/storefront/graphql",
    method: ["GET", "POST", "OPTIONS"],
    handler: async (req, reply) => {
      const tenant = resolveTenant(req);
      const yoga = createYoga({
        schema: createStorefrontSchema(tenant.id),
        graphqlEndpoint: "/api/storefront/graphql",
      });

      const response = await yoga.handleNodeRequestAndResponse(req.raw, reply.raw, {
        req,
        reply,
        tenant,
      } as any);

      reply.sent = true;
      return response;
    },
  });

  // Mount Admin GraphQL API Yoga handler
  app.route({
    url: "/api/admin/graphql",
    method: ["GET", "POST", "OPTIONS"],
    handler: async (req, reply) => {
      const tenant = resolveTenant(req);
      const yoga = createYoga({
        schema: createAdminSchema(tenant.id),
        graphqlEndpoint: "/api/admin/graphql",
      });

      const response = await yoga.handleNodeRequestAndResponse(req.raw, reply.raw, {
        req,
        reply,
        tenant,
      } as any);

      reply.sent = true;
      return response;
    },
  });

  return app;
}

export async function start() {
  const app = await buildApp();
  const PORT = parseInt(process.env.PORT || "4000", 10);
  const HOST = process.env.HOST || "0.0.0.0";

  try {
    await app.listen({ port: PORT, host: HOST });
    console.log(`🚀 VENDR Core Multi-Tenant API running at http://${HOST}:${PORT}`);
    console.log(`🛍️ Storefront GraphQL: http://${HOST}:${PORT}/api/storefront/graphql`);
    console.log(`⚡ Admin GraphQL: http://${HOST}:${PORT}/api/admin/graphql`);
  } catch (err) {
    app.log.error(err);
    process.exit(1);
  }
}

// Start if executed directly
if (import.meta.url === `file://${process.argv[1]?.replace(/\\/g, "/")}`) {
  start();
}

import { createSchema } from "graphql-yoga";
import { initialProducts } from "./sample-data.js";
import { CheckoutService } from "./checkout.js";

const typeDefs = /* GraphQL */ `
  type Query {
    shop: Shop!
    products(first: Int = 20): [Product!]!
    productByHandle(handle: String!): Product
    product(id: ID!): Product
    cart(id: ID!): Cart
  }

  type Mutation {
    cartCreate(input: CartInput): CartPayload!
    cartLinesAdd(cartId: ID!, lines: [CartLineInput!]!): CartPayload!
    cartLinesRemove(cartId: ID!, lineIds: [ID!]!): CartPayload!
    cartDiscountCodesUpdate(cartId: ID!, discountCodes: [String!]): CartPayload!
    checkoutComplete(cartId: ID!, email: String!, shippingAddress: AddressInput!): CheckoutPayload!
  }

  type Shop {
    name: String!
    primaryDomain: String!
    currencyCode: String!
  }

  type Product {
    id: ID!
    title: String!
    handle: String!
    description: String!
    descriptionHtml: String
    vendor: String!
    productType: String!
    status: String!
    tags: [String!]!
    images: [String!]!
    variants: [ProductVariant!]!
    totalInventory: Int!
  }

  type ProductVariant {
    id: ID!
    productId: ID!
    title: String!
    sku: String!
    price: Float!
    compareAtPrice: Float
    requiresShipping: Boolean!
    selectedOptions: [SelectedOption!]!
    inventoryQuantity: Int!
    image: String
  }

  type SelectedOption {
    name: String!
    value: String!
  }

  type Cart {
    id: ID!
    lines: [CartLine!]!
    subtotalAmount: Float!
    totalTaxAmount: Float!
    totalShippingAmount: Float!
    totalDiscountAmount: Float!
    totalAmount: Float!
    currencyCode: String!
    discountCodes: [String!]!
  }

  type CartLine {
    id: ID!
    merchandiseId: ID!
    quantity: Int!
    variant: ProductVariant!
  }

  type CartPayload {
    cart: Cart
    userErrors: [UserError!]!
  }

  type CheckoutPayload {
    orderNumber: Int
    orderId: ID
    totalAmount: Float
    status: String
    userErrors: [UserError!]!
  }

  type UserError {
    field: [String!]
    message: String!
  }

  input CartInput {
    lines: [CartLineInput!]
    discountCodes: [String!]
  }

  input CartLineInput {
    merchandiseId: ID!
    quantity: Int!
  }

  input AddressInput {
    firstName: String
    lastName: String
    address1: String!
    city: String!
    country: String!
    zip: String!
  }
`;

export function createStorefrontSchema(tenantId: string) {
  return createSchema({
    typeDefs,
    resolvers: {
      Query: {
        shop: () => ({
          name: "Apex Apparel Co.",
          primaryDomain: "apex-apparel.vendr.local",
          currencyCode: "USD",
        }),
        products: () => initialProducts,
        productByHandle: (_: unknown, { handle }: { handle: string }) =>
          initialProducts.find((p) => p.handle === handle),
        product: (_: unknown, { id }: { id: string }) =>
          initialProducts.find((p) => p.id === id),
        cart: (_: unknown, { id }: { id: string }) => CheckoutService.getCart(id),
      },
      Mutation: {
        cartCreate: async (_: unknown, { input }: any) => {
          try {
            const lines: { variant: any; quantity: number }[] = [];
            if (input?.lines) {
              for (const l of input.lines) {
                const foundVariant = initialProducts
                  .flatMap((p) => p.variants)
                  .find((v) => v.id === l.merchandiseId);
                if (foundVariant) {
                  lines.push({ variant: foundVariant, quantity: l.quantity });
                }
              }
            }
            const cart = await CheckoutService.createCart(tenantId, lines);
            if (input?.discountCodes) {
              for (const code of input.discountCodes) {
                await CheckoutService.applyDiscountCode(cart.id, code);
              }
            }
            return { cart, userErrors: [] };
          } catch (err: any) {
            return { cart: null, userErrors: [{ field: ["cart"], message: err.message }] };
          }
        },
        cartLinesAdd: async (_: unknown, { cartId, lines }: any) => {
          try {
            const mappedLines: { variant: any; quantity: number }[] = [];
            for (const l of lines) {
              const foundVariant = initialProducts
                .flatMap((p) => p.variants)
                .find((v) => v.id === l.merchandiseId);
              if (foundVariant) {
                mappedLines.push({ variant: foundVariant, quantity: l.quantity });
              }
            }
            const cart = await CheckoutService.addLines(cartId, mappedLines);
            return { cart, userErrors: [] };
          } catch (err: any) {
            return { cart: null, userErrors: [{ field: ["lines"], message: err.message }] };
          }
        },
        cartLinesRemove: async (_: unknown, { cartId, lineIds }: any) => {
          try {
            const cart = await CheckoutService.removeLines(cartId, lineIds);
            return { cart, userErrors: [] };
          } catch (err: any) {
            return { cart: null, userErrors: [{ field: ["lineIds"], message: err.message }] };
          }
        },
        cartDiscountCodesUpdate: async (_: unknown, { cartId, discountCodes }: any) => {
          try {
            let updatedCart;
            for (const code of discountCodes) {
              updatedCart = await CheckoutService.applyDiscountCode(cartId, code);
            }
            return { cart: updatedCart, userErrors: [] };
          } catch (err: any) {
            return { cart: null, userErrors: [{ field: ["discountCodes"], message: err.message }] };
          }
        },
        checkoutComplete: async (_: unknown, { cartId, email, shippingAddress }: any) => {
          try {
            const order = await CheckoutService.completeCheckout(cartId, email, shippingAddress);
            return {
              orderNumber: order.orderNumber,
              orderId: order.id,
              totalAmount: order.totalPrice,
              status: order.financialStatus,
              userErrors: [],
            };
          } catch (err: any) {
            return {
              orderNumber: null,
              orderId: null,
              totalAmount: null,
              status: null,
              userErrors: [{ field: ["checkout"], message: err.message }],
            };
          }
        },
      },
    },
  });
}

import { FastifyRequest } from "fastify";

export interface TenantContext {
  id: string;
  name: string;
  slug: string;
  domain?: string;
  currencyCode: "USD" | "EUR" | "GBP";
}

/**
 * Resolves the tenant context from the incoming HTTP request.
 * Supports subdomain extraction (e.g., apex-apparel.vendr.local),
 * custom domain headers, and explicit x-vendr-tenant override.
 */
export function resolveTenant(req: FastifyRequest): TenantContext {
  const customHeader = req.headers["x-vendr-tenant"] as string | undefined;
  if (customHeader) {
    return {
      id: `ten_${customHeader}`,
      name: customHeader.replace(/-/g, " ").toUpperCase(),
      slug: customHeader,
      currencyCode: "USD",
    };
  }

  const host = req.headers.host || "localhost";
  const parts = host.split(".");

  if (parts.length > 2 && parts[0] !== "www") {
    const slug = parts[0];
    return {
      id: `ten_${slug}`,
      name: slug.replace(/-/g, " ").toUpperCase(),
      slug,
      domain: host,
      currencyCode: "USD",
    };
  }

  // Default fallback store for standalone development
  return {
    id: "ten_apex_apparel",
    name: "Apex Apparel Co.",
    slug: "apex-apparel",
    domain: host,
    currencyCode: "USD",
  };
}

import crypto from "crypto";
import { WebhookPayload } from "@vendr/types";

export interface WebhookSubscriber {
  id: string;
  tenantId: string;
  topic: string;
  endpoint: string;
  secret: string;
}

export class WebhookDispatcher {
  private static subscribers: WebhookSubscriber[] = [];

  static register(sub: WebhookSubscriber) {
    this.subscribers.push(sub);
  }

  static async dispatch<T>(topic: string, tenantId: string, data: T): Promise<void> {
    const matching = this.subscribers.filter(
      (s) => s.tenantId === tenantId && (s.topic === topic || s.topic === "*")
    );

    const payload: WebhookPayload<T> = {
      id: `evt_${crypto.randomUUID()}`,
      topic,
      tenantId,
      apiVersion: "2026-10",
      createdAt: new Date().toISOString(),
      data,
    };

    const bodyString = JSON.stringify(payload);

    for (const sub of matching) {
      try {
        const hmac = crypto
          .createHmac("sha256", sub.secret)
          .update(bodyString, "utf8")
          .digest("base64");

        // Fire HTTP POST webhook event
        fetch(sub.endpoint, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "X-Vendr-Topic": topic,
            "X-Vendr-Hmac-Sha256": hmac,
            "X-Vendr-Tenant-Id": tenantId,
          },
          body: bodyString,
        }).catch((err) => {
          console.error(`[Webhook Dispatcher] Failed to deliver ${topic} to ${sub.endpoint}:`, err.message);
        });
      } catch (err) {
        console.error(`[Webhook Dispatcher] Error signing webhook:`, err);
      }
    }
  }
}
